import { axiosInstance } from './globalInstance';

class VideoApi {
  static async getListVideoRecording(appId) {
    const response = await axiosInstance({
      method: 'Get',
      url: `${process.env.API_URL}/app/${appId}/video-recording`,
      withCredentials: true,
    });
    return response;
  }

  static async getFilterAttribute(appId) {
    const response = await axiosInstance({
      method: 'Get',
      url: `${process.env.API_URL}/app/${appId}/video-recording/create`,
      withCredentials: true,
    });

    return response;
  }

  static async applyRule(ruleId, appId, _csrf) {
    return axiosInstance({
      method: 'PUT',
      // url: process.env.API_URL + '/app/' + self.props.appId + '/video-recording/'+self.state.selectedRule['_id']+'/apply',
      url: `${process.env.API_URL}/app/${appId}/video-recording/${ruleId}/apply`,
      data: {
        _csrf,
      },
      withCredentials: true,
    });
  }

  static async saveNewRule(data, appId) {
    return axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/app/${appId}/video-recording`,
      data,
      withCredentials: true,
    });
  }

  static async saveAndApplyRule(data, appId, ruleId) {
    return axiosInstance({
      method: 'PUT',
      url: `${process.env.API_URL}/app/${appId}/video-recording/${ruleId}`,
      data,
      withCredentials: true,
    });
  }

  static async deleteRule(appId, id, _csrf) {
    return axiosInstance({
      method: 'DELETE',
      url: `${process.env.API_URL}/app/${appId}/video-recording/${id}`,
      withCredentials: true,
      data: {
        _csrf,
      },
    });
  }

  static async addTeamMember(data, appId) {
    return axiosInstance({
      method: 'POST',
      // url:  API_URL+'auth/login',
      url: `${process.env.API_URL}/app/${appId}/team`,
      data,
      withCredentials: true,
    });
  }

  static async removeTeamMember(appId, data) {
    return axiosInstance({
      method: 'DELETE',
      url: `${process.env.API_URL}/app/${appId}/team`,
      data,
      withCredentials: true,
    });
  }

  static async updateUserRole(appId, data) {
    return axiosInstance({
      method: 'PUT',
      // url:  API_URL+'auth/login',
      url: `${process.env.API_URL}/app/${appId}/team/update`,
      data,
      withCredentials: true,
    });
  }

  static async resendInvite(appId, data) {
    return axiosInstance({
      method: 'POST',
      url: `${process.env.API_URL}/app/${appId}/team/resend-invite`,
      data,
      withCredentials: true,
    });
  }

  static async changeVideoRecordingStatus(appId, data) {
    return axiosInstance({
      method: 'PUT',
      url: `${process.env.API_URL}/app/${appId}/video-recording/toggle-video-recording`,
      data,
      withCredentials: true,
    });
  }

  static async changeSessionRecordingStatus(appId, data) {
    return axiosInstance({
      method: 'PUT',
      url: `${process.env.API_URL}/app/${appId}/session-recording/toggle-session-recording`,
      data,
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status < 401;
      },
    });
  }

  static async fetchData(data) {
    return axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL}/search_attribute`,
      data,
      withCredentials: true,
    });
  }

  static async inviteDeveloper(data, appId) {
    return axiosInstance({
      method: 'POST',
      // url:  API_URL+'auth/login',
      url: `${process.env.API_URL}/app/${appId}/team/members`,
      data,
      withCredentials: true,
    });
  }
}

export default VideoApi;
