export const useFetchScreenName = (queryKey: any, data: any) =>
  useQuery(
    queryKey,
    () =>
      videoApi
        .fetchData(data)
        .then((res) => {
          const responseData = res?.data?.data || [];
          return responseData?.length
            ? responseData.map((screen: any) => ({ value: screen, label: screen }))
            : [];
        })
        .catch((error) =>
          message.error(
            error?.response?.data?.error?.message || 'Unable to get screens'
          )
        ),
    {
      enabled: false,
    }
  );

