export const toggleAIForApp = async ({ orgId, appId, isAIEnabled }: { orgId: string, appId: string, isAIEnabled: boolean }) => {
  try {
    const response = await subscriptionApi.toggleAIForApp(orgId, appId, isAIEnabled);
    return response?.data;
  } catch (error) {
    const errorData = (error as any)?.response?.data?.error;
    const errorMessage =
      errorData?.message ||
      errorData?.non_field_errors?.[0] ||
      'Unable to toggle AI for app';

    message.error(errorMessage);
    throw error;
  }
};

